#!/usr/bin/env python3
"""Emit selected southern school cohorts; activate only after every source peer closes."""
import argparse,collections,gzip,hashlib,json
from decimal import Decimal
from pathlib import Path
from gap_school_south_fetch import AREA,ROOT
from gap_school_south_build import COLLECTION,native_sources,packed,number,write

EMPLOYERS={35:('langley-school-district','School District No. 35 (Langley)'),37:('delta-school-district','School District No. 37 (Delta)'),38:('richmond-school-district','School District No. 38 (Richmond)'),69:('qualicum-school-district','School District No. 69 (Qualicum)'),70:('pacific-rim-school-district','School District No. 70 (Pacific Rim)'),78:('fraser-cascade-school-district','School District No. 78 (Fraser-Cascade)'),79:('cowichan-valley-school-district','School District No. 79 (Cowichan Valley)')}
INDEX='https://www2.gov.bc.ca/gov/content/education-training/k-12/administration/financial-management/school-district-financial-reporting/statement-of-financial-information'

def sha(b):return hashlib.sha256(b).hexdigest()
def relative(p):return str(p.relative_to(ROOT))
def verified_ref(ref):
 p=ROOT/ref['path'];b=p.read_bytes();assert sha(b)==ref['sha256'],'Changed reviewed input '+str(p);return b

def emit(entry,check=False):
 n=entry['district'];candidate=json.loads(gzip.decompress(verified_ref(entry['selectedCandidate'])));peers=[]
 for p in entry['peerReviews']:verified_ref(p);peers.append(p)
 assert entry['status']!='verified' or peers,'Verified source requires pinned independent acceptance.'
 rows=candidate['rows'];assert not candidate.get('remainingFlags');source=candidate['source'] if n==37 else json.loads((AREA/f'sd{n}-sofi-2025-retrieval.json').read_text());context=json.loads((AREA/'source-context-primary-review.json').read_text());context=next((s for s in context['sources'] if s['district']==n),None);slug,name=EMPLOYERS[n];result=[]
 for scope in ['employee-remuneration','school-trustees']:
  xs=[r for r in rows if r['category']==scope];role='employees' if scope=='employee-remuneration' else 'trustees';key=f'sd{n}-2025-{role}';payload=[[slug,r['name'],r['position'],number(r['remuneration']),None if r['expenses'] is None else number(r['expenses']),r['pdfPage']] for r in xs];data,raw=packed(payload);file=key+'.json.gzip';write(COLLECTION/file,data,check)
  computed=[str(sum((Decimal(r[f]) for r in xs if r[f] is not None),Decimal(0))) for f in ['remuneration','expenses']];printed=candidate['controls'][scope]['literalPrintedControls'] if n==37 else context['literalPrintedControls'][scope];residual=[str(Decimal(a)-Decimal(b)) for a,b in zip(computed,printed)];qualified=any(Decimal(x)!=0 for x in residual);missing=sum(r['name'] is None for r in xs)
  evidence={'originalSourceSha256':source['sha256'],'selectedCandidate':entry['selectedCandidate'],'independentPeerReviews':peers,'sourceFields':xs,'literalPrintedComponentTotals':printed,'literalComputedComponentTotals':computed,'controlResiduals':residual,'residualCauseEstablished':None if not qualified else False,'sourceContext':context,'unknownNamePaymentRows':missing,'dataSha256':sha(data),'normalizedSha256':sha(raw),'noOutreach':True,'noCompiledRowsDeleted':True}
  blob,_=packed(evidence);efile=key+'-evidence.json.gzip';write(COLLECTION/efile,blob,check)
  warning='Fiscal-year payment disclosures are not annual base salary rates or a complete employee roster. Source blank/dash expenses remain unknown (null); explicit numeric zero remains zero. '
  if qualified:warning+=f'Literal {role} rows total ${computed[0]} remuneration/${computed[1]} known expenses versus printed ${printed[0]}/${printed[1]} (row sum minus printed: {residual[0]}/{residual[1]}). Causes are not established; no amounts are adjusted to balance. '
  if n==35:warning+='Starred expenses include travel for international student recruitment. '
  if n==37:warning+='Some names are visibly clipped by source cell masks; only visible fragments are retained. One employee payment has name unavailable because the next given-name glyph is partly clipped; its visible source fragment is retained in evidence. Hidden PDF overflow is not used to complete a name. '
  if n==38:warning+='Source expense footnotes identify international recruitment/program travel and partial/full reimbursements. Printed amounts are retained without netting. Separate trustee role/term observations are preserved even when a name repeats. The source spelling DISTRCT ADMINISTRATOR is retained. '
  if n==70:warning+='Employee position groups are sometimes visibly truncated; only printed prefixes are retained. Trustee positions are not published and remain null. '
  if n==78 and role=='employees':warning+='Employee positions are not published and remain null. '
  if n==79:warning+='Starred source expense cells include international student recruitment (*) or teacher remedy payments above $5,000 (**), so expenses mix travel/other expenses with some compensation. Source columns remain literal; teacher remedy payments are not moved into remuneration. Some long titles are visibly truncated. '
  warning+='Existing compiled observations remain retained where equivalence of complete cohorts and reporting periods has not been proved.'
  fields={'id':'gap-fill-school-south-'+key,'employerSlug':slug,'employerName':name,'sector':'School districts','year':'2024/25','slug':'2024-25','periodType':'fiscal','periodStart':'2024-07-01','periodEnd':'2025-06-30','title':name+', fiscal year ended June 30, 2025: '+role,'sourceUrl':source['sourceUrl'],'sourceIndexUrl':'https://www.deltasd.bc.ca/district/financial-information/' if n==37 else INDEX,'sha256':source['sha256'],'file':file,'dataSha256':sha(data),'normalizedSha256':sha(raw),'provenanceFile':efile,'provenanceSha256':sha(blob),'category':scope,'scope':scope,'scopeDescription':'Complete published '+('employee payment schedule above the stated disclosure threshold' if role=='employees' else 'trustee/elected-official payment schedule'),'currency':'CAD','amountUnit':'dollars','amountPrecision':'whole-dollars' if n in [35,37,38] else 'cents','threshold':75000 if role=='employees' else None,'thresholdComparison':'>' if role=='employees' else None,'nameDisclosure':'visible-source-fragments-with-one-unavailable-name' if n==37 and role=='employees' else 'source-name-as-disclosed','positionDisclosure':'not-published' if (n==70 and role=='trustees') or(n==78 and role=='employees') else 'source-visible-text-only','pages':sorted({r['pdfPage'] for r in xs}),'rowCount':len(xs),'totalRemuneration':number(computed[0]),'totalExpenses':number(computed[1]),'status':entry['status'],'sourceKind':'official','completeEmployeeSchedule':role=='employees','verifiedOn':'2026-11-02' if entry['status']=='verified' else None,'publicWarning':warning,'notes':['Both raw extraction readers and original source images remain retained. Guarded agreement and finite source-image benchmarks do not establish infallible transcription.','Below-threshold totals, employer CPP/EI, suppliers and financial statements are excluded from individual salary records.','No expense amount was imputed from a blank or OCR absence; no amounts were adjusted to balance totals.'],'validation':{'originalFingerprintVerified':True,'independentReaderMethods':candidate.get('readers', ['Tesseract full original300dpi TSV row geometry','RapidOCR Paddle independent line/box geometry']),'rowsIndependentlyCheckedByBothReaders':len(xs),'personalSourceReadScope':'All true field flags, recovered rows and low-score agreement cases; independent peer flags/withheld benchmarks/context/census. Not a second personal transcription of every observation.','rowsByPhysicalPage':dict(collections.Counter(r['pdfPage'] for r in xs)),'printedControlTotals':printed,'computedComponentTotals':computed,'controlResiduals':residual,'summaryReconciles':not qualified,'residualCauseEstablished':False if qualified else None,'knownExpenseValueCount':sum(r['expenses'] is not None for r in xs),'nullExpenseRows':sum(r['expenses'] is None for r in xs),'zeroExpenseRows':sum(r['expenses'] is not None and Decimal(r['expenses'])==0 for r in xs),'negativeExpenseRows':sum(r['expenses'] is not None and Decimal(r['expenses'])<0 for r in xs),'unknownNamePaymentRows':missing,'completeEmployeeSchedule':role=='employees','compiledPartitionRetained':True,'compiledPartitionRetentionReason':'Complete official-source versus compiled-cohort equivalence and exact reporting period have not been proved.','independentPeerReviews':peers,'selectedCandidate':entry['selectedCandidate']}}
  result.append(fields)
 return result

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');ap.add_argument('--activate',action='store_true');args=ap.parse_args();config=json.loads((AREA/'selected-source-acceptance.json').read_text());sources=native_sources(args.check)
 for entry in config['sources']:sources+=emit(entry,args.check)
 verified=all(s['status']=='verified' for s in sources);manifest={'version':1,'reviewed':verified,'rowSchema':['employerSlug','name','position','remuneration','expenses','pdfPage'],'sources':sources};blob=(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n').encode();write(COLLECTION/'source-candidates.json',blob,args.check)
 if args.activate:
  assert verified,'All ten original source peer reviews must close before activation.';write(COLLECTION/'sources.json',blob,args.check)
 print(json.dumps({'sources':len(sources),'rows':sum(s['rowCount'] for s in sources),'verifiedSources':sum(s['status']=='verified' for s in sources),'activated':args.activate}))
if __name__=='__main__':main()
